const stageReceiptPath = String(env.JARVIS_HUMO17_CORE_STAGE_RECEIPT || "").trim();
let stageReceipt = null;
let coreStageReceiptSha256 = "";
let coreStageEvidenceSource = "physical_stage_receipt";
if (stageReceiptPath && fs.existsSync(stageReceiptPath)) {
    stageReceipt = JSON.parse(fs.readFileSync(stageReceiptPath, "utf8"));
    if (stageReceipt.ok !== true || stageReceipt.physicalStageCertified !== true || stageReceipt.coreManifestVerified !== true ||
        stageReceipt.persistentRuntimeReady !== true || stageReceipt.offlinePaidBootstrapRequired !== true || stageReceipt.persistentRuntimeSystemToolsReady !== true || stageReceipt.persistentRuntimeProvisionImageTag !== RUNPOD_HUMO17_CORE_CACHE_BASE.provisionImageTag || stageReceipt.persistentRuntimeExpectedRegistryDigest !== RUNPOD_HUMO17_CORE_CACHE_BASE.expectedRegistryDigest || stageReceipt.persistentRuntimeOperatingSystem !== RUNPOD_HUMO17_CORE_CACHE_BASE.operatingSystem || !String(stageReceipt.persistentRuntimePythonVersion || "").startsWith(RUNPOD_HUMO17_CORE_CACHE_BASE.pythonVersionPrefix) || !String(stageReceipt.persistentRuntimeTorchVersion || "").startsWith(RUNPOD_HUMO17_CORE_CACHE_BASE.torchVersionPrefix) || !String(stageReceipt.persistentRuntimeTorchCudaVersion || "").startsWith(RUNPOD_HUMO17_CORE_CACHE_BASE.torchCudaVersionPrefix) || Number(stageReceipt.persistentRuntimeRequiredAssetCount || 0) !== RUNPOD_HUMO17_CORE_CACHE_BASE.requiredFiles.length ||
        stageReceipt.terminationVerified !== true || stageReceipt.networkVolumeRetained !== true ||
        stageReceipt.networkVolumeId !== volume.id || stageReceipt.networkVolumeDataCenterId !== volume.dataCenterId ||
        stageReceipt.newPersistentBytes !== RUNPOD_HUMO17_CORE_CACHE_BASE.totalBytes ||
        stageReceipt.combinedPersistentBytes !== RUNPOD_HUMO17_CORE_CACHE_BASE.combinedPersistentBytes) throw new Error("HUMO17_STAGE_RECEIPT_INVALID");
    coreStageReceiptSha256 = createHash("sha256").update(fs.readFileSync(stageReceiptPath)).digest("hex");
} else {
    const durablePreflightPath = path.join(resolvedRoot, ".sia7", "humo17-quality-201f-final-preflight.json");
    if (!fs.existsSync(durablePreflightPath)) throw new Error("HUMO17_STAGE_RECEIPT_REQUIRED");
    let durablePreflight = null;
    try { durablePreflight = JSON.parse(fs.readFileSync(durablePreflightPath, "utf8")); }
    catch { throw new Error("HUMO17_DURABLE_CORE_EVIDENCE_INVALID"); }
    const durableReceiptSha256 = String(durablePreflight?.coreStageReceiptSha256 || "").trim().toLowerCase();
    if (durablePreflight?.ok !== true || durablePreflight?.status !== "HUMO17_RUNTIME_ZERO_COST_PREFLIGHT_READY" ||
        durablePreflight?.cheapCpuRecertificationRequired !== false || durablePreflight?.resourceCreated !== false ||
        durablePreflight?.inferenceStarted !== false || Number(durablePreflight?.activePods) !== 0 || Number(durablePreflight?.paidStaleReceipts) !== 0 ||
        durablePreflight?.terminationVerified !== true || durablePreflight?.networkVolumeRetained !== true ||
        durablePreflight?.networkVolumeId !== volume.id || durablePreflight?.volumeId !== volume.id || durablePreflight?.dataCenterId !== volume.dataCenterId ||
        durablePreflight?.coreManifestVerified !== true || !String(durablePreflight?.coreStagePodId || "").trim() ||
        !/^[a-f0-9]{64}$/.test(durableReceiptSha256)) throw new Error("HUMO17_DURABLE_CORE_EVIDENCE_INVALID");
    stageReceipt = { podId: String(durablePreflight.coreStagePodId).trim() };
    coreStageReceiptSha256 = durableReceiptSha256;
    coreStageEvidenceSource = "durable_zero_cost_preflight";
}
